def update_graph(graph, shortest_dists, visited_length) -> list:
    for i, j in list(enumerate(graph)):
        if not i == j: # Iterate over all edges (but not self-loops)
            if shortest_dists[graph[i]] > shortest_dists[graph[j]] + j: # Check the path
                # Update the graph
                graph[i] = graph[j]
                graph, shortest_dists[i][i] = update_dist(visited_length, shortest_dists), update_dist(visited_length, shortest_dists)
                graph[i] = i
    return graph


def update_dist(visited_length, shortest_dists) -> list:
    for i, j in list(enumerate(shortest_dists)):
        if not i == j: # Iterate over all nodes in the graph
            shortest_dists[i][i] = 0 if visited_length == len(shortest_dists) - 1 else shortest_dists[i][i] + j
    return shortest_dists

