def solve(n, edges, s, t):
    g = list()  # Graph is represented as a list of nodes.
    for i in range(n):
        g.append(i)

    # Tracks tree distance.
    dist = [float('inf')] * n

    # We look at nodes in the order they are introduced.
    # For each node that gets introduced, look at all the adjacent edges.
    for u, v, w in edges:
        # First, ensure v is in the graph.
        for node, i in enumerate(g):
            if v == i:
                dist[node] = w
                break

        # Then, ensure u is in the graph.
        for node, i in enumerate(g):
            if u == i:
                # We add the edge.
                dist[g.index(v)] += dist[i]
                g[v].append(u)
                break

    return min(dist if s != t else [0])  # When s == t, the distance is 0.


