            if min_dists[u] != float('inf') and min_dists[v] > min_dists[u] + w:
                return -1  # negative cycle

    # reconstruct path and return min distance
    if t in prevs:
        path = [t]
        while t != s:
            t = prevs[t]
            path.append(t)
        return len(path)
    else:
        return 0

