from typing import List
from typing import Tuple
class Node(object):
    val: int
    min_level: int
    children: Dict[int, Tuple[int, Node]]
    max_level: int

    def __init__(self):
        self.children = {}
        self.min_level = 0
        self.max_level = 0

    def size(self) -> int:
        """A function that returns the total size of all values in the tree."""
        total = 0
        for elem in self.children:
            total += self.children.get(elem)[0]
            total += self.children[elem][0].size()
        return total

    @property
    def ancestors(self):
        """A function that returns a List containing all _ancestors_ of this node. A node's ancestor is a list containing one or more nodes from its branch"""
        plist = []
        level = 0
        ver = self
        while ver:
            if level != ver.min_level and level != ver.max_level:
                plist.append(ver)
            level = ver.min_level if ver.min_level < ver.max_level else ver.max_level
            ver = ver.parent
        return [el.val for el in plist]

    def add(self, vectors) -> Tuple[int, int]:
        """A function that adds to the tree one or more node with their given vectors. If vectors.length is equal to or greater than two, the function looks at two nodes at a time and wants to find the minimal Manhattan distance between them across their branches (min(|vv1 - vv2|)). Then the nodes are moved their Manhattan distance closer one another, and returned this distance. That number is attributed to the current node as its height. All vectors are sorted (1 dimension). Ancestors' vectors are changed too. Please remember that vectors are integer lists and Manhattan distance for two vectors a and b is given by 2|a - b|.

