class Stack(object):
    def __init__(self):
        self.items = []

    def is_empty(self):
        return self.items == []

    def push(self, data):
        self.items.append(data)

    def pop(self):
        """ Return content and pop it from the stack. positive i means item i will be removed 
        from the stack, this function removes/recycles item from place i"""
        content = self.items.pop()
        return content

    def __repr__(self):
        return " ".join([str(self.items)])

