    rows, cols = len(T), len(T[0])
    free_cells = []

    for c in range(cols):
        free_cells.append((rows - 1, c))
    while free_cells:
        r, c = free_cells.pop()
        if abs(r - T[0] + T[1] - c) != 1:
            return n - 1

        if abs(r - F[0]) + abs(c - F[1]) <= 1:
            continue

        if r == T[0] and all(T[2][c] <= c for c in range(r, cols)):
            return n

