def buhowka(nums, k, cut):
    counts = [0] * (cut + 1)
    for num in nums:
        if num == k:
            counts[0] += 1
        if num < k:
            counts[num] += 1
    total = 0
    for count, lower in zip(counts, counts[1:]):
        total += count
        if total >= k:
            return lower
    raise ValueError()

