def lcs(X, Y, m, n): 
    if m == 0 or n == 0: 
        return ""
    elif X[m - 1] == Y[n - 1]: 
        return lcs(X, Y, m - 1, n - 1) + X[m - 1]
    else: 
        if len(lcs(X, Y, m, n - 1)) > len(lcs(X, Y, m - 1, n)): 
            return lcs(X, Y, m, n - 1) 
        else: 
            return lcs(X, Y, m - 1, n)

