    def move(node):
        val = grid[node['row'] - 1][node['col']]
        if val != '#' and node['row'] != 0:
            node['row'] -= 1
            node['val'] = val
        elif val != '#' and node['row'] != len(grid)-1:
            node['row'] += 1
            node['val'] = val
        elif val != '#' and node['col'] != 0:
            node['col'] -= 1
            node['val'] = val
        elif val != '#' and node['col'] != len(grid[0])-1:
            node['col'] += 1
            node['val'] = val
        else:
            return None
    def next(node):
        if type(node['children']) == tuple:
            del node['children']
            children = node['children']
            for child in children:
                move(child)
                if child['row'] != node['row'] or child['col'] != node['col']:
                    child['children'] = next(child) + (child,)
            return children
        else:
            return node['children']
    def visit(node, goal_found):
        node['visited'] = (goal_found, node)
        if node['val'] == "#":
            return
        else:
            node['children'] = next(node)
            for child in node['children']:
                visit(child, goal_found)
    start = { 'row': start[0] + 1, 'col': start[1] + 1, 'val': grid[0][0], 'visited': (goal_found, start)}
    visit(start, False)
    result = [start['visited'][1]]
    while goal_found not in start['visited']:
        start, goal_found = start['visited'][1], start['visited'][0]
        result.append(start)
    return result[::-1]

