class TrieNode:
    def __init__(self):
        self.children = {}
        self.word, self.count = None, None
    def __str__(self):
        return "TrieNode({}, {})".format(self.word and self.word.__repr__().replace("'","\\'"), self.count)
    def __repr__(self):
        return self.__str__()
    def is_root(self):
        return self.word is None
    def is_word(self):
        return self.word is not None
    def has_children(self) -> bool:
        return all([child.is_root() for child in self.children.values()])

    def add(self, word: str) -> bool:
        cnt = self.count if self.count else 0
        if word in self.children: return False
        self.children[word] = TrieNode()
        self.children[word].word, self.children[word].count = word, cnt
        return True

    def longest_word(self) -> Option[(str, int)]:
        return reduce(lambda rt, child: Option[(rt, child.count) if child.is_word() else rt], self.children.values(), Option.None)

    def count(self, word: str) -> int:
        if self.is_word(): return self.count
        choice = self.children[word]
        return choice.count if choice.is_word() else 0


