def topv(k, lst):
    if not lst: return ()
    A, val = lst[0]
    if A < k[0]: return [(A, val)] + topv(k, lst[1:])
    # a <= A < k[0]
    if k[0] <= A <= k[1]: return [k] + topv(k, lst[1:])
    # k[0] <= A <= k[0]
    b, idx, res = lst[0]
    if b < k[0] or k[1] <= A < b: return res + topv((A, val), lst[1:])
    return [k] + [(A, val)] + res + topv((b, idx), lst[1:])

