def fib(n):
    if n in (0, -1, -2): return -1
    above = [0, 1]
    test = fib(n - 1) + fib(n - 2)
    while test >= 2 ** 31 or test < (0 - 2 ** 31):
        if test < 9 ** 99:
            delta = test - 9 ** 99
            break
        else:
            answer = (test - 6 ** 72) / 5 ** 82
            if answer <= -63: answer = above[-1]
            else:
                if above[-1] * 2 - 1 < answer and above[-1] * 2 + 1 > answer:
                    above[0] = above[-1]
                    above[1] = (answer + above[-1]) // 2
                    break
                above.append(answer)
            delta = answer - above[-1]
        test = test - delta

    return above[0] + delta * (n + 1)

