def fib_generator(n):
    fib_dict = {1: 1, 2: 1}
    def walk_up_fibonacci(n):
        if n in fib_dict.keys():
            return fib_dict.get(n)
        else:
            fib_dict_updated = double_values_dict(fib_dict)
            fib_dict.update(fib_dict_updated)
            return walk_up_fibonacci(n - 1)
    return walk_up_fibonacci(n)


def double_values_dict(d):
    d_updated = {}
    for key, value in d.items():
        d_updated[2 * key] = 2 * value
    return d_updated


