    cached = cache.get(key)
    if cached != None:
        return cached
    if n in (0, 1):
        return {}, n
    if n < past_items_count or n < current_item + 2 * past_items_count:
        out_fib = current_item, n - current_item - past_items_count
        cached[key] = out_fib
        return cached, out_fib
    (subbed_past_items, subbed_current), subbed_n = fib_recursive_cached(
        n - past_items_count - current_item,
        current_item + past_items_count,
        current_item,
        cache
    )
    o = (past_items_count, current_item, n)
    cached[key] = fib_recursive_cached(o, 3)
    return cached, o

