def dijkstra_shortest_path(g, start: int, dist: int):
    s = [(dist, start)]
    d = [i for i in range(len(g))]
    while len(d) < len(g) and len(s) < len(g):
        d[i], i = min(d[i], [dist, v] in s)
        for j, v in enumerate(g[i]):
            if (dist + v < d[j]) and (j not in s): s.append((dist + v, d))

