    def rely(job, inspected, order): 
        if inspected is False: return False
        if inspected == job: return True
        for i in job_table[job]:
            if i not in inspected or rely(i, inspected - {i}, order):
                orders[order.index(i)] = job
                order[job] = i
                return True
        return False
    job = orders[0]
    while job is not None:
        job = rely(job, set(range(n)), orders)

    return order

