def solve(n, edges):
    if n <= 1:
        return True

    # Adjency Matrix
    matrix = [False] * n

    # Set boolean element to true if u && v in relationships
    for u, v in edges:
        matrix[u] = True
        matrix[v] = True

    # Find a single SCC
    # Topological Index should occur to find a cycle
    stack = list()
    color = list()

    for i in range(n):
        color.append(0)
        top = -1
        if matrix[i]:
            top += 1
            stack.append(i)

        while top != -1:
            node = stack[top]
            if color[node] == 0:
                top -= 1

            for next_node in range(n):
                if color[next_node] == 0 and matrix[node] and matrix[next_node]:
                    color[node] = 1
                    color[next_node] = 1
                    top += 1
                    stack.append(next_node)
            else:
                color[node] = 2
                top -= 1

    # Find connected component length
    component_length = 0
    for color_c in color:
        if color_c == 0:
            component_length += 1

    # Exit if total component's length is greater than 2
    if component_length > 2:
        return True

    # Find an SCC
    for t in range(n):
        color[t] = 0

    stack = list()
    top = -1
    for i in range(n):
        if color[i] == 0 and matrix[i]:
            top += 1
            stack.append(i)

        while top != -1:
            node = stack[top]
            top -= 1

            for next_node in range(n):
                if color[next_node] == 0 and matrix[next_node] and not matrix[node]:
                    stack.append(next_node)
                    top += 1
                    color[next_node] = 1

    # Find a Connected Component
    component_length = 0
    for color_c in color:
        if color_c == 0:
            component_length += 1

    # Exit if the total component's length is not equal to 1
    if component_length >= 2:
        return True

