def depth_search(g, start, seen):
    stack, result = [start], []

    while stack:
        x = stack.pop()
        if not seen.add(x): continue
        result.append(seen.copy())
        result.extend([y for y in g[x] if y not in seen])
        for y in sorted(g[x], reverse=True):
