    # first level has rows
    # second index has cols
    # final key has string
    default_dict = defaultdict(lambda x:[[],[],[]])

    # row is traversed inside the for loop 
    for row in range(n):
#       column is constructed with rows of 30 values inside a list 
       for loop in range(len(default_dict)):
            # each position in row has len 30 x 5 characters In text
            counter = 0
            for position in range(len(default_dict[row][loop])):
                # position less than 30 then add character to first layer string
                if counter!=10:
                    default_dict[row][loop].append(chr(97 +position))
                # position equal to 30 then add number to second layer string
                else: default_dict[row][loop].append(str(counter))
                if position > 15:
                    # position greater than 30 then add backspace and carriage return to the third layer
                    default_dict[row][loop].append('\b')
                    default_dict[row][loop].append('\r')
                if position > 16:
                    # position greater than 31 then do not add any new character 
                    default_dict[row][loop].append(" ")

                counter+=1

    print(default_dict[n][2][1])

