def dfs(adj_matrix, node):
    # Not visited all the nodes to start with.
    stack = [node]
    visited = [0 for x in range(len(adj_matrix))]
    visited[node] = -1
    connected = [-1]
    while len(stack) > 0:
        node = -1
        for i in range(len(stack)):
            if not visited[stack[i]]:
                node = stack[i]
            if node != -1:
                break
        if node == -1:
            return connected
        for next_node in range(len(adj_matrix[node])):
            if adj_matrix[node][next_node] == 1 and not visited[next_node]:
                stack.append(next_node)
                visited[next_node] = -1  # adding to the DFS stack
        connected.append(node)
    return connected

