def solve(n, edges):
    visited, path, components = set(), [], []

    def dfs(current):
        visited.add(current)
        path.append(current)
        for neighbor in edges:
            # Checking if the neighbor is unvisited!
            if neighbor[0] == current and neighbor[1] not in visited:
                try: # Trying to traverse the unvises path, returning False if loop detected
                    path.append(neighbor[1]) #Appending node to path
                    dfs(neighbor[1])
                # If a loop was detected and failed append set the path back to null
                except: path = []
            elif neighbor[1] == current and neighbor[0] not in visited:
                try:
                    path.append(neighbor[0])
                    dfs(neighbor[0])
                except: path = []

    for vertex in range(n):
        if vertex not in visited:
            #starts dfs on every node unless it is visited 
            dfs(vertex)
            #Adds the lenght of the path created(it can only be one node long becuase each dfs traverse will add a single vertex to the path) to a new list that will be iterated
            #over at the end of the function
            components.append(len(path))
            #Resets path at the end of each dfs traverse
            path = []
    return len(components)

