def shortest_path(n, edges, s, t):
    def recursively_build_tree(s):
        g[s] = [i for _, i in edges]
        for x, y, w in edges:
            if s != x:
                g[x] = g[s]
                g[x].append(y)
        for start in g:
            if not sorted(sortedUnion(g[start]), key = (lambda x: x[1]))[0][1]: return None
        return g
    def sortedUnion(tree):
        for node in range(len(tree)):
            for target in range(len(tree)):
                if tree[node][1] == tree[target][1]: continue
                curr_diff = abs(tree[target][1] - tree[node][1]) - 1
                curr_length = tree[node][0] + tree[target][0] + curr_diff
                if curr_length < tree[target][0] or (curr_length == tree[target][0] and tree[target][1] > tree[node][1]):
                    tree[target] = (curr_length, curr_diff, tree[node]) # overwrite
        return filter(lambda x: x, tree)
    g = recursively_build_tree(s)
    if g == None: return None
    curr = g[t]
    dist, path = recursively_calc_dist(s, t, g, curr)
    return path + [t] * path.count(t) if path[-1] != t else None

def recursively_calc_dist(s, t, tree, curr):
    if curr == [t]: return [t], 0
    dist, diff, pred = tree[curr][0], tree[curr][1], tree[curr][2]
    if curr == [t]: pred = None
    path, new_curr = recursively_calc_dist(s, t, tree, pred) if pred is not None else ([], [])
    return [curr] + path if curr != [t] else [curr], path + [curr] + [t]

