def my_bisect_left(nums, element):
    left, right, counter = 0, len(nums) - 1, 0
    while right + 1 > left:
        middle = (left + right) // 2
        if element <= nums[middle]:
            if nums[middle] == element:
                counter += 1
                right = middle
            else:
                left = middle
        else:
            right = middle
    if nums[left] == element and element in nums:
        counter += 1
    elif element not in nums:
        print(f"ERROR!!! missing item {element}!" )
        return [-1, -1]
    elif element in nums and nums[right] == element:
        counter += 1
    return [left, right]

