class UnionFind:
    def __init__(self, n):
        self.nodes = list(range(n))
        self.rank = [1] * n
        self.fixed_index = [i for i in range(n)]
        self.fixed_index[0] = None

    @classmethod
    def create_by(cls, iterable):
        return cls(len(iterable))

    def find(self, a):
        if not self.fixed_index[a]:
            return a
        self.fixed_index[a] = self.find(self.fixed_index[a])
        return self.fixed_index[a]

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            if self.rank[ra] < self.rank[rb]:
                ra, rb = rb, ra
            self.rank[ra] += self.rank[rb]
            if self.rank[ra] > self.rank[rb]:
                self.fixed_index[rb] = ra
            else:
                self.fixed_index[ra] = rb

