def solve(n, edges):
    # Set of unique edges
    edges = {tuple(e) for _, e in edges}

    # We start off with a graph built of all edges in the edges set.
    graph = set()

    # Keep adding all edges in the set to the graph...
    for tupl in edges:
        begin, end = tupl
        graph.add(begin)
        graph.add(end)

    # If graph has just one element, it is a connected component
    if n == len(graph):
        return 1
    else:
        # Prepare lists to hold component's node ids and edges
        components = []
        component_edges = []

        # Visit each node node by node
        for n_id in range(n):
            # If this node does not belong to any component, add it
            if n_id not in graph:

                # To find out which components it does belong to...
                visit_queue = [n_id]
                comp_edges = set()

                # And then keep visiting every node that is connected to it
                while visit_queue:
                    begin = visit_queue.pop()
                    comp_edges.add(begin)

                    # Add n_id to a current component
                    components.append(begin)

                    for edge in edges:
                        # If this node and to the visited nodes, add newly visited node to a queue
                        if tuple(edge) == (begin, n_id) or tuple(edge) == (n_id, begin):
                            visit_queue.append(n_id)

                # Remove these nodes from the edges set, which implies leaving behind only pair's edges that connect separate components
                graph -= comp_edges
                component_edges += comp_edges

        # If there are two or more components, we finally have the number of connected components
        if len(components) >= 2:
            return len(components)
        else:
            # Otherwise, the graph has a connected component tree
            return 1

