def reduceAndSort(cc: Union[type(None), List[int]]) -> int:
    """Return the number of components by reducing the list, preserving its ordering.
    cc should be a list of connected components. Output in list of integers"""

    c = cc[0] if cc else 0
    for cc_new in cc[1:]:
        c += int(len(cc_new) / len(set(cc_new)))
    return c

def solve(n, edges):
  if len(edges) == 0: return n
  cyclic = [False for _ in range(n)]
  reachable = [n] * n
  for edge in edges:
    a, b = edge
    if not cyclic[a] and not reachable[b]:
      return 0
    if not cyclic[b] and not reachable[a]:
      cyclic[a] = True
      cyclic[b] = True
      reachable[a] = 0
      reachable[b] = 0
  return n - sum(reachable)

