        return is_open

    def can_open_down(row, col):
        if inside(row + 1, col):
            is_open = not grid[row + 1][col] in ['#', '@']
        else: is_open = False
        return is_open

    def can_open_left(row, col):
        if inside(row, col - 1):
            is_open = not grid[row][col - 1] in ['#', '@']
        else: is_open = False
        return is_open

    def can_open_right(row, col):
        if inside(row, col + 1):
            is_open = not grid[row][col + 1] in ['#', '@']
        else: is_open = False
        return is_open

    def explore(row, col):
        if row == goal[0] and col == goal[1]:
            path.append((row, col))
