        if (row, col) in visited:
            return False

        open_directions = {'#', '@' if not (row, col) == start else '#'}
        cannot_open_directions = {'#', '@', r'@'}
        for dp in (can_open_top(row, col), can_open_down(row, col), can_open_left(row, col), can_open_right(row, col)):
            if dp and grid[row][col] not in cannot_open_directions:
                continue
