                continue
            if not explore(row + 1 if up else row - 1 if down else row, col + 1 if right else col - 1 if left else col):
                continue
            grid[row][col] = '*'  # mark any new cell visited
            path.append((row, col))
            visited.add((row, col))
            return True

        return False

    while not explore(row, col):
        # no need to mark next cell as visited #
        del path[-1]
        path[-1] = (row, col)
