    for prev in range(n):
        for u, v, w in edges:
            if prev == u:
                if distances[v] > distances[u] + w:
                    distances[v] = distances[u] + w
                    parents[v] = u

    # Step two, contraction of edges
    max_dist = 0  # maximum distance encountered in a relaxation step

    # Run step one. A relaxation from u to v is a state change when
    # C(u) + w(u, v) < D(v).
    while (max_dist := max(max_dist, max(distances) - distances[0])) != 0:
        # Run step zero, relaxing a bond between parents
        for v, u in zip(distances, parents):
            if u >= 0:
                v += u  # d(v) += cost(u, v)
                distances[v] = v
            # The nodes will remain ordered s.t.
            # 0 <= d(v) <= max(d(v)).

        # Run step one, relaxing a bond
        for prev in range(max_dist, 0, -1):
            for u, v, w in edges:
                if prev == parents[u]:
                    if distances[v] > distances[u] + w:
                        distances[v] = distances[u] + w
                        parents[v] = u
            # A relaxation between parents increases max_dist.

    if distances[t] == INF:
        return -1
    return distances[t]

