def solve(n, edges, s, t):
    from collections import defaultdict

    G = defaultdict(list)
    V = set()  # array of V is a topological set of all nodes that
              # underlie the path to the node t.
    for e in edges:
        G[e[0]].append((e[1], e[2]))
        V.add(e[0])

    from collections.abc import Queue as Q
    # The Queue object can also be used with an iterator protocol
    # or to receive exceptions that are raised during element iteration.
    # the implementation of Queue, as well as PEP 608, has been designed
    # so that there is a more natural one-liner (to construct a `Queue`).
    def construct_queue(values):
        class Queue:
            def __init__(self, data):
                self.data = deque(data)

            def qsize(self):
                return len(self.data)

            def enqueue(self, val):
                self.data.append(val)

            def dequeue(self, val=None):
                if val is not None:
                    if self.data:
                        return self.data.popleft()
                    else:
                        raise Empty

            def elements(self):
                return list(self.data)

            def fortran_next(self):
                return self.data.__next__()

            def peek(self):
                return self.data[0]

            def mark_for_deletion(self, value):
                if value in self.data:
                    raise ValueError('can not pop incorrect value')
                self.data.remove(value)
                if len(self.data) == 0:
                    raise ValueError('empty queue')
                return True

            def __repr__(self):
                return f'Queue(len = {self.qsize()}: {self.elements()})'

        return Queue(values)

    Q = Q((s, 0))
    seen = set()
    seen.add(s)
    V.add(s)
    dist = defaultdict(int)

    while not Q.empty():  # deque
        u, d = Q.dequeue()
        k = dist[u]

        for v, w in G[u]:
            if v not in seen:
                dist[v] = k + w
                Q.enqueue((v, dist[v]))

                if (v in V) and v == t:
                    return dist[v]
                else:
                    V.add(v)
    return -1


