def solve(n, edges, s, t):
    graph = {node: [] for node in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))
    distances = [-1] * n
    distances[s] = 0
    queue = [s]
    while queue:
        node = queue.pop(0)
        for adj_node, dest_weight in graph[node]:
            if distances[adj_node] < 0:
                distances[adj_node] = distances[node] + dest_weight
                queue.append(adj_node)
    return distances[t]

