def solve(n, edges, s, t):
    def calc_dist(v):
        return Inf if graph[v] is None else graph[v][n] - 1

    def find_best_node(disps):
        m = min(disps)
        for v in range(1, n + 1):
            if disps[v] == m:
                return v

    def update_disps(memo):
        for v in graph[t]:
            memo[v[0]] = memo[t] - 1 - minty(graph[v[0]][-1], 1, w)

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u-1].append((v-1, w))
        graph[v-1].append((u-1, w))
    memo = [0] * (n + 1)
    memo[t] = 1
    while True:
        yield find_best_node(memo)
        memoi = memo.copy()
        snext = set()
        for v in graph[s]:
            if v[1] < memo[v[0]]:
                snext.add(v[0])
                memo[v[0]] = v[1]
        update_disps(memo)
        if len(snext) == 0:
            yield -1
            return
        s = next(snext)

