def solve(cost, s, t, leaf):
    leafs = [leaf for _ in range(1<<leaf.size())]
    res = float('inf')
    dgraph = defaultdict(list)
    leafs = [leaf for _ in range(1<<leaf.size())]
    for f, [u,v,c] in enumerate(cost):
        dgraph[(u,v)] += c
        dgraph[(v,u)] += c
        if f == t:
            res = c
    for k, vs in enumerate(leafs):
        _res = float('inf')
        while len(deque(vs)) > 1:
            vs = deque(vs)
            for _ in range(1000):
                if len(vs) <= 1: break
                num = vs.popleft()
                vs.append(((num + 1) >> 1, _) ^ num)
        else:
            _res = vs.popleft()
        res = min(_res, res)
    return res

