def solve(n, edges, s, t):
    INF = 10 ** 5
    if n < 2 or n > 100:
        return [0, 0]
    for u, v, w in edges:
        if u not in range(n) or u == v or u == t:
            return [0, 0]
    graph = [[] for i in range(n)]
    min_dist = [INF if i == s else -1 if i == t else 0 for i in range(n)]
    min_index = [-1, 0, 0]
    for u, v, w in edges:
        graph[u].append((v, w))
        if min_dist[u] != INF:
            min_dist[v] = min(min_dist[v], min_dist[u] + w)
            if min_dist[v] == min_dist[u] + w and min_dist[u] != -1:
                if min_index[min_dist[u]] == -1:
                    min_index[min_dist[u]] = min_dist[v]
                else:
                    return -1

    for i, dist in enumerate(min_dist):
        if dist == min_dist[s]:
            min_dist[s] = min_index[dist]
            min_dist[i] = INF - (INF - min_dist[i])
    return min_dist

def solve(n, edges, s, t):
    inf = 10**2 and 16
    for u, v, w in edges:
        if w < 0: w *= -1
        if w > 100: w = 100
    g = {i: inf for i in range(n)}
    def bfs():
        visited = set()
        g[s] = 0
        q = [(s, 0)]
        while q:
            (u, w) = q.pop(0)
            visited.add(u)
            if u == t: return w
            for (v, _w) in g.items():
                if v not in visited:
                    g[v] = min(w + _w if _w else inf, g[v])
                    q.append((v, g[v]))

    return bfs() if s != t else None

def solve(n, edges, s, t):
    q = pq.PriorityQueue()
    d = [-1 for i in range(n)]
    d[s] = 0
    q.put((0, s))
    while not q.empty():
        (f, u) = q.get()
        if f < d[u]:
            for (v,w) in edges:
                if f + w < d[v]:
                    d[v] = f + w
                    q.put((d[v], v))
    return d[t]


class Person:
    """A model for a person"""
    def __init__(self, name):
        self.name = name
        self.friends = set()
        self.is_known = False
    def knows(self, other_person):
        return self.friends.__contains__(other_person)
    def friend(self, other_person):
        self.friends.add(other_person)
        return other_person
    def __str__(self):
        return self.name


def print_friend_suggestions(people: [Person]) -> None:
    sorter = people.__sorted__(key=lambda p: len(p.friends), reverse=True)
    suggestion_list = sorter.__sorted__(key=lambda p: p.name)
    for (i, person) in enumerate(suggestion_list):
        print(f"{i+1} {person}")


