    INF = 100
    def get_shortest_path(s, t, node_costs, adj_list):
        costs_queue = priority_queue.empty()
        costs_queue.insert((0, s))
        shortest_path_costs = {}
        shortest_path_costs[s] = 0
        while costs_queue:
            (cost, node) = costs_queue.pop()
            if node == t:
                return cost
            elif node not in shortest_path_costs:
                for adj in adj_list[node]:
                    if shortest_path_costs[adj] is None:
                        costs_queue.insert((cost + node_costs[adj], node))
                        shortest_path_costs[adj] = node_costs[adj] + cost
                        if adj == t:
                            return node_costs[adj] + cost
        return INF

    costs = {}
    shortest_path_costs = {}

    for x, y, w in edges:
        if y not in costs:
            costs[y] = INF
            shortest_path_costs[y] = None
        if x not in costs:
            costs[x] = INF
            shortest_path_costs[x] = None
        costs[y] = min(costs[y], w + costs[x])
        costs[x] = min(costs[x], w + costs[y])

    return max((get_shortest_path(s, t, node_costs, adj_list) if node_costs[node] != INF else None for node in costs), default=INF)

