        # Backtrack if no path found from this cell
        path.pop()
        return False

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    if find_path(start[0], start[1]):
        return path
    else:
        return []

